package com.adaptiq.model;
import java.time.Instant;
public final class Recommendation { private Long recommendationId,studentId,topicId; private String topicName,recommendationText,status; private Difficulty recommendedDifficulty; private Instant createdAt;
 public Long getRecommendationId(){return recommendationId;} public void setRecommendationId(Long v){recommendationId=v;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public Long getTopicId(){return topicId;} public void setTopicId(Long v){topicId=v;} public String getTopicName(){return topicName;} public void setTopicName(String v){topicName=v;} public String getRecommendationText(){return recommendationText;} public void setRecommendationText(String v){recommendationText=v;} public Difficulty getRecommendedDifficulty(){return recommendedDifficulty;} public void setRecommendedDifficulty(Difficulty v){recommendedDifficulty=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} @Override public String toString(){return (topicName==null?"Topic":topicName)+" • "+recommendationText+" ["+recommendedDifficulty+"]";} }
